def nav(prefix=''):
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container header-inner"><a class="brand" href="{prefix or './'}" aria-label="Mauricio Ruiz home"><span class="monogram">MR.</span><span class="brand-name">Mauricio Ruiz</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu <span aria-hidden="true">☰</span></button><nav id="main-nav" aria-label="Main navigation"><a href="{prefix}#work">Work</a><a href="{prefix}#experience">Experience</a><a href="{prefix}#writing">Life in Data</a><a href="{prefix}#contact">Contact</a><a class="button button-small button-outline" href="{prefix}assets/mauricio-ruiz-profile.pdf" download>Download profile <span aria-hidden="true">↓</span></a></nav></div></header>'''

def assistant():
 return '''<button class="assistant-launcher" data-open-assistant aria-haspopup="dialog"><span aria-hidden="true">✧</span> Ask my AI assistant</button><dialog id="assistant-dialog" aria-labelledby="assistant-title"><div class="assistant-head"><div><span class="eyebrow">A CONVERSATION, GROUNDED IN MY WORK</span><h2 id="assistant-title">Ask my AI assistant</h2></div><button class="close-dialog" aria-label="Close assistant">×</button></div><p class="assistant-note">Ask about my projects, experience or skills. AI can make mistakes; check important details against the original sources.</p><p class="assistant-external"><a href="https://mauricio-ai-cv-assistant.streamlit.app" target="_blank" rel="noopener noreferrer">Open in a new tab ↗</a><span>First launch may take a moment.</span></p><iframe data-src="https://mauricio-ai-cv-assistant.streamlit.app/?embed=true" title="Mauricio Ruiz AI portfolio assistant" loading="lazy"></iframe></dialog>'''

def footer(prefix=''):
 return f'''<footer class="site-footer container"><a class="brand" href="{prefix or './'}"><span class="monogram">MR.</span><span>Curiosity. Evidence. Action.</span></a><p>© <span data-year>2026</span> Mauricio Ruiz · Dublin, Ireland</p><a href="#top">Back to top ↑</a></footer>{assistant()}'''

def doc(title,description,body,prefix='',path=''):
 canonical='https://ruizmielesmauricio.github.io/mauricio-s_portfolio/'+path
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#f8f8f2"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{canonical}"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"><script defer src="{prefix}assets/main.js"></script></head><body id="top">{nav(prefix)}{body}{footer(prefix)}</body></html>'''

def art(p,prefix=''):
 if p['image']:
  return f'<div class="project-image {p["slug"]}"><img src="{prefix}assets/{p["image"]}" alt="{escape(p["alt"])}" loading="lazy" width="800" height="480"></div>'
 return '<div class="project-image assistant-art" aria-hidden="true"><div class="chat-mark">✧</div><div class="chat-bubble">What have you built with Python?</div><div class="chat-bubble reply">Let’s explore the projects. <span>● ● ●</span></div><div class="rag-label">DOCUMENTS <span>→</span> RETRIEVAL <span>→</span> ANSWERS</div></div>'

def card(p,index):
 tags=''.join(f'<span>{escape(t)}</span>' for t in p['tags'])
 return f'''<article class="project-card" data-category="{p['category']}">{art(p)}<div class="project-copy"><div class="project-meta"><span>{p['category']}</span><span>0{index+1}</span></div><h3><a href="projects/{p['slug']}.html">{p['title']}</a></h3><p>{p['summary']}</p><div class="tags">{tags}</div><a class="text-link" href="projects/{p['slug']}.html">View case study <span aria-hidden="true">↗</span></a></div></article>'''

